import numpy as np
from numba import njit

@njit(cache=True)
def _auction(C):
    n=C.shape[0]; price=np.zeros(n); owner=np.full(n,-1,np.int32); assign=np.full(n,-1,np.int32)
    eps=1.0
    while eps>1e-6:
        eps*=.2; owner[:]=-1; assign[:]=-1
        stack=np.arange(n,dtype=np.int32); top=n
        while top:
            top-=1; i=stack[top]; best=1e100; second=1e100; bj=-1
            for j in range(n):
                v=C[i,j]+price[j]
                if v<best: second=best; best=v; bj=j
                elif v<second: second=v
            old=owner[bj]; price[bj]+=second-best+eps; owner[bj]=i; assign[i]=bj
            if old>=0: assign[old]=-1; stack[top]=old; top+=1
    return assign

class Solver:
    def __init__(self):
        _auction(np.zeros((2,2)))
    def solve(self,problem,**kwargs):
        M=np.asarray(problem['cost_matrix']); c=_auction(M); n=len(c)
        G=np.zeros(M.shape); G[np.arange(n),c]=np.asarray(problem['source_weights'])
        return {'transport_plan':G}
